BEGIN;
-- PT109-S3-Q5
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT109-S3-Q5$batch01$ AND q.stimulus=$batch01$The radiation absorbed by someone during an ordinary commercial airline flight is no more dangerous than that received during an ordinary dental X-ray. Since a dental X-ray does negligible harm to a person, we can conclude that the radiation absorbed by members of commercial airline flight crews will also do them negligible harm.$batch01$ AND q.prompt=$batch01$A flaw in the argument is its failure to consider that$batch01$ AND q.correct_choice=$batch01$D$batch01$) THEN RAISE EXCEPTION 'Question changed: PT109-S3-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT109-S3-Q5$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT109-S3-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT109-S3-Q5$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$there may be many forms of dangerous radiation other than X-rays and the kinds of radiation absorbed by members of commercial airline flight crews$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT109-S3-Q5 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT109-S3-Q5$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$receiving a dental X-ray may mitigate other health risks, whereas flying does not$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT109-S3-Q5 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT109-S3-Q5$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$exposure to X-rays of higher intensity than dental X-rays may be harmful$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT109-S3-Q5 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT109-S3-Q5$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$the longer and the more often one is exposed to radiation, the more radiation one absorbs and the more seriously one is harmed$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT109-S3-Q5 D'; END IF; END $guard$;
