INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT109-S3-Q5$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$Radiation absorbed by airline flight crews does negligible harm.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$Radiation absorbed on *one ordinary commercial flight* is no more dangerous than radiation from *one ordinary dental X-ray*, and one dental X-ray does negligible harm.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$The comparison changes its unit. A passenger takes one flight; a crew member takes many. Even if one exposure is harmless, repeated exposures might add up to harmful levels. Ask the author to compare cumulative exposure over the same period, not one flight against one X-ray.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the objection that dose depends on duration and frequency, which the one-flight comparison omits.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT109-S3-Q5$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$Other kinds of dangerous radiation do not challenge the conclusion about the radiation crews actually absorb. This would help only if crews were exposed to one of those other kinds.$batch01$), ($batch01$B$batch01$, $batch01$A dental X-ray might offset some other risk, but the evidence says the X-ray itself does negligible harm. The conclusion concerns radiation harm, not total health benefits of dentistry versus flying.$batch01$), ($batch01$C$batch01$, $batch01$Higher-intensity X-rays may be harmful. The argument compares an ordinary dental X-ray to an ordinary flight; it does not claim that every X-ray exposure is harmless.$batch01$), ($batch01$D$batch01$, $batch01$The more often and longer someone is exposed, the more radiation that person can absorb. Crew members' repeated flights could cause nonnegligible harm even if the radiation from a single flight is as harmless as that from a single dental X-ray. This is the missing difference in the comparison.$batch01$), ($batch01$E$batch01$, $batch01$Additional risks of flying may matter to airline crews' overall health, but the conclusion is limited to harm from radiation. An objection needs to make the radiation conclusion doubtful.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT109-S3-Q5$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
